  "inlineSchema": "// Configuración de la conexión\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// -------------------------------------------------------------\n// ENUMS (Tipos de datos con opciones fijas)\n// -------------------------------------------------------------\nenum Role {\n  ADMINISTRADOR\n  EMPLEADO\n  CLIENTE\n  INVITADO\n}\n\nenum ReservationStatus {\n  PENDIENTE_DE_PAGO\n  CONFIRMADA\n  CANCELADA\n}\n\nenum PaymentMethod {\n  TARJETA\n  EFECTIVO\n}\n\nenum PaymentStatus {\n  PENDIENTE\n  PAGADO\n  RECHAZADO\n}\n\n// -------------------------------------------------------------\n// MODELOS / TABLAS\n// -------------------------------------------------------------\n\n// 1. Usuarios del Sistema\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String\n  nombre    String\n  rol       Role     @default(CLIENTE)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  reservas Reservation[]\n}\n\n// 2. Catálogo de Habitaciones\nmodel Room {\n  id           String   @id @default(uuid())\n  numeroCuarto String   @unique\n  tipo         String // Ej: Suite, Doble, Individual\n  precioNoche  Float\n  descripcion  String?\n  videoUrl     String? // URL para streaming de video promocional\n  imagenes     String[] // Arreglo de URLs con imágenes WebP\n  disponible   Boolean  @default(true)\n  createdAt    DateTime @default(now())\n\n  reservas Reservation[]\n}\n\n// 3. Reservas\nmodel Reservation {\n  id            String   @id @default(uuid())\n  nombreTitular String\n  email         String // Para confirmación y factura\n  documentoId   String // DPI / Pasaporte\n  telefono      String\n  fechaCheckIn  DateTime\n  fechaCheckOut DateTime\n  adultos       Int\n  ninos         Int\n\n  // Datos de Facturación\n  nit             String?\n  nombreFiscal    String?\n  direccionFiscal String?\n\n  estado ReservationStatus @default(PENDIENTE_DE_PAGO)\n  total  Float\n\n  // Relación opcional con Usuario (Permite reserva como Guest/Invitado)\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id])\n\n  // Relación con Habitación\n  roomId String\n  room   Room   @relation(fields: [roomId], references: [id])\n\n  pago    Payment?\n  factura Invoice?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// 4. Pagos (Stripe / Efectivo)\nmodel Payment {\n  id                    String        @id @default(uuid())\n  monto                 Float\n  metodo                PaymentMethod\n  estado                PaymentStatus @default(PENDIENTE)\n  stripePaymentIntentId String? // ID de transacción retornado por Stripe\n\n  reservationId String      @unique\n  reservation   Reservation @relation(fields: [reservationId], references: [id])\n\n  createdAt DateTime @default(now())\n}\n\n// 5. Empleados\nmodel Employee {\n  id        String   @id @default(uuid())\n  nombre    String\n  puesto    String\n  telefono  String\n  email     String   @unique\n  createdAt DateTime @default(now())\n}\n\n// 6. Proveedores\nmodel Supplier {\n  id        String   @id @default(uuid())\n  nombre    String\n  empresa   String\n  telefono  String\n  email     String\n  servicio  String\n  createdAt DateTime @default(now())\n}\n\n// 7. Servicios Adicionales (Restaurante, Bar, Parqueo, Piscinas)\nmodel AdditionalService {\n  id        String   @id @default(uuid())\n  categoria String // RESTAURANTE, BAR, PARQUEO, PISCINA\n  nombre    String\n  precio    Float\n  createdAt DateTime @default(now())\n}\n\n// 8. Facturas\nmodel Invoice {\n  id               String @id @default(uuid())\n  numeroFactura    String @unique\n  nit              String\n  nombreFiscal     String\n  direccion        String\n  montoAlojamiento Float\n  montoServicios   Float  @default(0)\n  montoTotal       Float\n\n  reservationId String      @unique\n  reservation   Reservation @relation(fields: [reservationId], references: [id])\n\n  createdAt DateTime @default(now())\n}\n\n// prisma/schema.prisma\n\nenum EstadoTurno {\n  ACTIVO\n  FINALIZADO\n}\n\nmodel Workstation {\n  id        String      @id @default(uuid())\n  nombre    String // Ej: \"Recepción PC-01\", \"Caja PC-02\"\n  codigo    String      @unique // Ej: \"REC-PC1\"\n  ubicacion String // Ej: \"Lobby Principal\", \"Restaurante\"\n  activa    Boolean     @default(true)\n  createdAt DateTime    @default(now())\n  updatedAt DateTime    @updatedAt\n  turnos    WorkShift[]\n}\n\nmodel WorkShift {\n  id            String      @id @default(uuid())\n  userId        String // ID del Empleado\n  workstationId String // ID de la Computadora asignada\n  workstation   Workstation @relation(fields: [workstationId], references: [id])\n  inicioTurno   DateTime    @default(now())\n  finTurno      DateTime?\n  estado        EstadoTurno @default(ACTIVO)\n}\n",
